1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Step = {
9	  op: string;
10	  items?: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: Step[];
16	};
17	
18	export type QuoteResult = {
19	  premium: number;
20	};
21	
22	export type ScenarioResults = {
23	  results: QuoteResult[];
24	};
25	
26	const PROCESSING_FEE = 5;
27	
28	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  rune: 25,
34	  moonstone: 25,
35	};
36	
37	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
38	
39	const addPercent = (amount: number, percent: number): number =>
40	  amount + (amount * percent) / 100;
41	
42	const itemBasePremium = (item: Item): number =>
43	  BASE_PREMIUM_BY_TYPE[item.type];
44	
45	const BLOCK_SIZE = 3;
46	
47	const BLOCK_PREMIUM = 60;
48	
49	const sumOf = (amounts: number[]): number =>
50	  amounts.reduce((sum, amount) => sum + amount, 0);
51	
52	const formsABlock = (alikeItems: Item[]): boolean =>
53	  alikeItems.length === BLOCK_SIZE;
54	
55	const sumOfItemBasePremiums = (items: Item[]): number =>
56	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
57	
58	const groupByType = (items: Item[]): Item[][] => {
59	  const groups = new Map<string, Item[]>();
60	
61	  for (const item of items) {
62	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
63	  }
64	
65	  return [...groups.values()];
66	};
67	
68	const alikeGroupBasePremium = (alikeItems: Item[]): number =>
69	  formsABlock(alikeItems) ? BLOCK_PREMIUM : sumOfItemBasePremiums(alikeItems);
70	
71	const policyBasePremium = (items: Item[]): number =>
72	  sumOf(groupByType(items).map(alikeGroupBasePremium));
73	
74	const roundPremiumInMHPCOsFavor = (amount: number): number =>
75	  Math.ceil(amount);
76	
77	const quotePremium = (items: Item[]): number =>
78	  roundPremiumInMHPCOsFavor(
79	    addPercent(policyBasePremium(items), FIRST_INSURANCE_SURCHARGE_PERCENT) +
80	      PROCESSING_FEE,
81	  );
82	
83	export const runScenario = (scenario: Scenario): ScenarioResults => ({
84	  results: scenario.steps.map((step) => ({
85	    premium: quotePremium(step.items ?? []),
86	  })),
87	});
